def solve(inputs: dict) -> float:
    x = inputs["x"]
    steps = inputs["steps"]

    # Mask to keep within 32 bits
    mask = (1 << 32) - 1

    for _ in range(steps):
        x ^= (x << 11) & mask
        x ^= (x >> 9)
        x ^= (x << 15) & mask
        x &= mask

    return float(x)
